@import '@alfalab/core-components-button/src/vars.css';

/* prettier-ignore */
@each $size, $border-radius in
    (32, --button-xxs-size-mobile-border-radius),
    (40, --button-xs-size-mobile-border-radius),
    (48, --button-s-size-mobile-border-radius),
    (56, --button-m-size-mobile-border-radius),
    (64, --button-l-size-mobile-border-radius),
    (72, --button-xl-size-mobile-border-radius) {
    .size-$(size) {
        border-radius: var($(border-radius));
    }
}
